"""V2 field guide: optional learning routes, modest rewards, explicit detection."""
def extend(quest,quests,check,item_task):
 def chain(group,prefix,rows,root='bienvenida'):
  previous=root
  for key,title,item,text in rows:
   identifier=prefix+'_'+key
   suffix=('\n\nObjetivo detectado: llevá el objeto en el inventario, sin consumirlo. Tener un trofeo no certifica una muerte propia; también podés conseguirlo comerciando.' if item else '\n\nActividad guiada: revisá o practicá estos pasos y marcá la casilla. Esta acción no se detecta automáticamente.')
   quest(identifier,title,group,item or 'minecraft:book',text+suffix,item_task(item) if item else check('Revisé / practiqué este paso'),[previous]);previous=identifier
 chain('27 · Un mundo nuevo','v2_mundo',[
  ('rumbo','Elegir tu primera ruta',None,'La v2 empieza de cero. Salí del pueblo caminando, marcá su posición en Xaero y elegí una ruta corta. Las montañas de Terralith y los biomas de Regions Unexplored cambian el viaje; rodear un macizo suele ser mejor que escalarlo sin equipo.'),
  ('equipo','Viajar ligero y preparado','minecraft:compass','Llevá comida, antorchas, bloques, cama o saco y una herramienta de repuesto. Marcá casa y pueblo en el mapa. La brújula no reemplaza una ruta de regreso y no evita perder objetos al morir.'),
  ('mapa','Leer el paisaje',None,'Un camino, una silueta sobre una colina o un barco pueden indicar una estructura. Observá desde afuera antes de entrar. Las fortalezas gigantes son expediciones; las cabañas y campamentos permiten exploraciones más cortas.'),
  ('andesita','Piedra para tu taller','minecraft:andesite','Terralith ReStoned devuelve vetas de andesita, granito y diorita. La andesita sigue siendo útil para Create. JEI muestra recetas alternativas; no necesitás encontrar un bioma especial para comenzar la industria.'),
  ('base','Dejar espacio al camino',None,'Buscá una zona fuera del spawn y de los accesos de aldeas. Protegé primero tu casa con Open Parties and Claims. No reclames entradas de mazmorras ni cofres comunitarios: su contenido personal debe seguir accesible para otros.'),
  ('ritmo','Una salida con una meta',None,'Elegí un objetivo por sesión: reconocer un valle, traer madera nueva o visitar una aldea. Quien juega más puede cartografiar y abrir caminos; quien juega menos conserva su botín de Lootr y sus misiones personales.')])
 chain('28 · Aldeas que funcionan','v2_aldea',[
  ('llegar','Conocer una comunidad',None,'Integrated Villages reemplaza las aldeas simples por pueblos temáticos. Algunas incorporan máquinas de Create y bloques de otros mods. Recorré caminos y edificios; no todas las aldeas tienen todos los servicios.'),
  ('guardias','Entender a los guardias',None,'Guard Villagers protege a los habitantes. No ataques aldeanos ni pruebes armas junto a ellos. Reclutar o equipar guardias requiere respetar sus condiciones; no son una fuente gratuita de equipo ni una excusa para vaciar aldeas.'),
  ('mecanismos','Mirar antes de tocar','create:andesite_alloy','Observá ejes, engranajes y fuentes de rotación. Mantené W sobre componentes en JEI para Ponder cuando esté disponible. Si una máquina no gira, revisá energía, orientación y estrés antes de cambiar bloques.'),
  ('cofres','Compartir el descubrimiento',None,'Abrí los cofres convertidos por Lootr aunque otra persona haya llegado antes. Los cofres normales, barriles propios y drops de criaturas no se convierten en recompensas personales por arte de magia. Identificá el contenedor antes de repartir.'),
  ('convivencia','Una aldea para todos',None,'Conservá camas, puestos de trabajo, iluminación y accesos. No desarmes el mecanismo principal para ahorrarte cuatro engranajes. Copiá la idea en tu taller y llevate una foto con Exposure.'),
  ('conexion','Unir pueblo, base y mercado',None,'Señalizá una ruta y compartí coordenadas sin revelar bases privadas. Waystones requiere descubrir los destinos y puede cobrar experiencia. Un camino o una ruta de barco permite viajar sin teletransporte.')])
 chain('29 · Arqueología de Create','v2_ruinas',[
  ('senales','Leer las ruinas de IDAS',None,'IDAS incorpora campamentos, casas, excavaciones y grandes complejos. Una ruina pequeña sirve para aprender a explorar; fortalezas, laberintos y torres arcanas merecen preparación. No confundas decoración con seguridad.'),
  ('sondeo','Reconocer antes del asalto',None,'Dejá una salida despejada, un punto de reunión y un cofre propio protegido fuera de la estructura. Identificá entradas, alturas y spawners. Evitá cavar a ciegas debajo de salas peligrosas.'),
  ('mecanica','La herramienta del arqueólogo','create:wrench','La llave de Create permite entender y orientar componentes. Usala con cuidado: arrancar un eje puede detener puertas o plataformas. Probá primero los controles visibles y conservá el mecanismo cuando puedas.'),
  ('muestra','Recuperar, estudiar, fabricar','create:brass_ingot','Un componente encontrado sirve como muestra para JEI. El objetivo es aprender a producirlo en tu base: calor, mezclado, transporte y energía. El botín no entrega automáticamente un rango ni completa la cooperación.'),
  ('magia','Industria y magia se complementan',None,'Las torres y ruinas pueden usar Ars Nouveau, Iron’s Spellbooks y Create. Llevá utilidad además de daño: luz, movilidad, comida y una forma de retirarte. Las restricciones personales de magia del servidor siguen vigentes.'),
  ('restaurar','Devolverle vida a una ruina',None,'Después de explorar, proponé restaurar una construcción pequeña que no bloquee contenido público. Planificá acceso, protección y un taller propio. No tapes cofres Lootr ni arenas de jefes con un claim.')],'explorador')
 chain('30 · Grandes fortalezas','v2_fortaleza',[
  ('observar','La escala cambia el riesgo',None,'When Dungeons Arise añade fortalezas, navíos y construcciones enormes. Están más separadas que los puntos de interés pequeños. Ver una desde lejos no significa estar preparado para saquearla entera.'),
  ('roles','Preparar una expedición',None,'Acordá quién abre camino, quién lleva provisiones y quién cubre la retirada. No son clases obligatorias. Dos amigos con funciones claras pueden coordinarse mejor que un grupo que entra corriendo por separado.'),
  ('campamento','Un regreso posible','minecraft:white_bed','Prepará un punto seguro fuera de la estructura y marcá el camino. Probá el punto de reaparición cuando el mundo permita camas. Nunca uses camas en Nether o End. Guardá equipo de rescate en tu base.'),
  ('avance','Limpiar por sectores',None,'Iluminá y asegurá una sala antes de avanzar. Enemigos de distintos pisos pueden acumularse; retirarse conserva recursos. No hace falta terminar toda la fortaleza en una sesión.'),
  ('botin','Recompensas sin carrera',None,'Lootr reparte cofres convertidos por jugador, sin reinicios para farmear. Las nuevas tablas reducen materiales finales en grandes cantidades. Los trofeos únicos siguen valiendo; los drops del suelo se reparten por acuerdo.'),
  ('registro','Dejar un informe útil',None,'Compartí nombre de la estructura, coordenadas, entrada y peligros. Una foto y un waypoint ayudan a los que se conectan después. No anuncies una zona como segura si quedan pisos sin revisar.')],'explorador')
 chain('31 · Los cuatro desafíos','v2_duelo',[
  ('reglas','Invocar lejos de casa',None,'Meet Your Fight ofrece cuatro jefes invocables. Buscá un lugar abierto, lejos del pueblo, aldeas, bases y construcciones ajenas. El invocador se consume. Acordá el reparto de drops antes de comenzar.'),
  ('swampjaw','Swampjaw: el primer desafío','meetyourfight:fossil_bait','Fabricá el cebo fósil con materiales comunes y aleación de andesita. El jefe vuela y usa ataques de área: dejá espacio para moverte, observá sus señales y llevá un arma a distancia.'),
  ('bellringer','Bellringer: el sonido del peligro','meetyourfight:haunted_bell','En Virgos la campana requiere latón y dientes de Swampjaw. Conservá sus trofeos o intercambiá con un compañero. Buscá ventanas de ataque y no gastes todo cuando el jefe no sea vulnerable.'),
  ('fortuna','Dame Fortuna: leer la jugada','meetyourfight:devils_ante','La apuesta requiere fantoplasma de Bellringer. Prestá atención a las cartas y a los cambios de fase. La preparación sirve, pero golpear sin observar no reemplaza resolver la mecánica.'),
  ('rosalyne','Rosalyne: el duelo final','meetyourfight:dusk_key','La llave del ocaso usa el trofeo de Fortuna y mecanismos de precisión de Create. Prepará movilidad y resistencia. Podés fabricar la llave en grupo; tenerla no obliga a invocar inmediatamente.'),
  ('recuerdos','Trofeos que cuentan una historia',None,'Guardá un trofeo, fabricá el accesorio que encaje con tu estilo y compartí los sobrantes. Passage’s Toll no se fabrica en Virgos por su teletransporte a través de paredes. Repetir un jefe es opcional; no concede rangos de cooperación.')],'explorador')
 chain('32 · Guardianes del mundo','v2_guardian',[
  ('pistas','Encontrar un santuario',None,'Bosses of Mass Destruction añade Night Lich, Void Blossom, Nether Gauntlet y Obsidilith. Sus arenas pertenecen al mundo. Revisá pistas, objetos y avances del mod; la ubicación no se entrega como un teletransporte desde el spawn.'),
  ('lich','Night Lich: preparar la noche',None,'Las Soul Stars permiten buscar y activar el encuentro del Night Lich. Consultá sus usos y reuní lo necesario antes de viajar. El combate no mantendrá al resto del servidor atrapado en una noche permanente.'),
  ('flor','Void Blossom: mirar bajo tierra',None,'Explorá las profundidades con salida, iluminación y espacio para esquivar. Observá el terreno de la arena antes de iniciar el combate. La flor tiene ataques de área: juntarse todos en un mismo punto puede ser peligroso.'),
  ('guante','Nether Gauntlet: control del espacio',None,'Llevá protección contra fuego y una ruta de retorno. Respetá el espacio del jefe y sus fases. Virgos desactiva el depósito adicional de ancient debris al morir para evitar que repetirlo sustituya la búsqueda del material.'),
  ('obelisco','Obsidilith: una arena en el End',None,'Llegá con bloques y una forma segura de cruzar islas. Observá los pilares y patrones del jefe. Dejá una ruta de regreso que también puedan usar compañeros con menor movilidad.'),
  ('cataclysm','Elegir el siguiente gran objetivo',None,'Cataclysm, Mowzie, Twilight y los nuevos guardianes ofrecen retos diferentes. No hay una obligación de matar todo en orden. Las pruebas Resonancia, Forja y Umbral siguen siendo las metas cooperativas que reconocen participación personal.')],'explorador')
 chain('33 · Mares y cielos','v2_travesia',[
  ('puerto','Preparar la tripulación','smallships:oak_cog','Antes de zarpar, llevá provisiones y acordá paradas. Seven Seas añade grandes barcos como puntos de exploración. Acercate con cuidado: una cubierta despejada puede ocultar enemigos debajo.'),
  ('hielo','Aquamirae: aguas peligrosas',None,'Aquamirae añade criaturas y ruinas ligadas a mares fríos. Prepará respiración, movilidad bajo el agua y un refugio en superficie. No conviertas la primera inmersión en una expedición con todo tu equipo valioso.'),
  ('capitana','La historia de Cornelia',None,'Investigá las estructuras y los objetos de Aquamirae; JEI y los avances orientan hacia el encuentro de la capitana. Separá objetos de invocación de materiales comunes. Elegí el momento con el grupo.'),
  ('cielo','Aether con nuevos horizontes',None,'Deep Aether amplía el Aether con biomas, recursos y mazmorras. Primero prepará el portal y comprendé cómo caés o regresás. Las islas no perdonan saltos sin una ruta segura.'),
  ('tormenta','La mazmorra de latón',None,'Buscá el contenido y los avances de Deep Aether para preparar su mazmorra y el Eye of the Storm. El nombre latón no significa que cualquier pieza de Create active el encuentro: revisá el bloque y la receta exactos.'),
  ('album','Una travesía compartida',None,'Documentá una costa, un barco y una isla con Exposure. Construir muelles, cartografiar y preparar provisiones son aportes útiles para quienes disfrutan menos del combate.')],'explorador')
 chain('34 · Otros horizontes','v2_dimensiones',[
  ('nether','Incendium: volver a mirar el Nether',None,'Incendium renueva terreno, biomas y estructuras del Nether. Sumado a las fortalezas de YUNG y ruinas de IDAS, hay rutas de distinta dificultad. No entres sin comida, resistencia al fuego y coordenadas del portal.'),
  ('ruta','Caminos que evitan pérdidas',None,'Señalizá túneles y puentes, cerrá bordes y dejá ancho para cruzarse. Construir una ruta segura es progreso compartido sin regalar equipo final. No bloquees entradas de estructuras públicas.'),
  ('stronghold','Una fortaleza con mecanismos',None,'Integrated Stronghold reemplaza la fortaleza del portal con una construcción más compleja, integrada con Create y otros mods. Los ojos de ender siguen siendo una pista. Probá controles antes de destruir los mecanismos.'),
  ('end','Nullscape: un End distinto',None,'Nullscape cambia las islas exteriores y su relieve. Guardá coordenadas, bloques y suministros de vuelta. Alcanzar una isla no garantiza que puedas regresar; quien aún no tiene élitros necesita caminos.'),
  ('cuevas','No olvidar Alex’s Caves',None,'Las cuevas especiales siguen una investigación propia: cabañas, mapas, tablillas y compendio. La brújula de biomas no localiza sus biomas en Virgos. Descubrir la cueva y luego automatizar materiales con Create son etapas distintas.'),
  ('compartir','Tu próxima aventura',None,'Elegí una meta de construcción, exploración o combate. El códice conserva progreso individual, los cofres Lootr permiten acompañar más tarde y las expediciones Virgos exigen cooperación. No necesitás jugar todos los días para tener un lugar en el grupo.')],'explorador')
 # Update the existing dimension introductions instead of leaving contradictory text.
 quests['end']['display']['description']='Buscá Integrated Stronghold con ojos de ender y explorá sus mecanismos de Create. Coordiná el primer viaje al End; Nullscape renueva las islas exteriores. El dragón no sustituye las pruebas cooperativas de Virgos.'
 quests['aether']['display']['description']='El Aether y Deep Aether ofrecen islas, biomas y mazmorras. Prepará su portal y una forma segura de moverte y regresar. El capítulo 33 continúa la guía.'
